// bench.js -- all sequencing logic for the f_ Max test bench.
// Spec/plan/tasks: .specify/test_bench/
//
// The patch (generated by make_bench.py) is only objects and wiring; every
// decision happens here. Classic `js`, ES5.
//
// Inlets:  0  OSC from [udpreceive 7471]:  /ping   /run <abs job dir>
//          1  Max errors: [error 1] -> [deferlow] -> [prepend bench_error]
//          2  per-frame draw bang from [jit.world bench_ctx], via [t b b]
//             so it arrives BEFORE the frame's textures flow
// Outlet:  0  OSC to [udpsend 127.0.0.1 7472]:  /pong  /done <dir>  /busy <dir>
//
// Modes:
//   "stub"         finish immediately                         (Phase 1)
//   "stub_delay"   finish after job.delay_ms (tests /busy)     (Phase 1)
//   "correctness"  one pass on bench_p1, capture one frame     (Phase 2)
//   "performance"  K chained slots, fps vs a K=0 baseline       (Phase 4)
//
// Correctness frame sequence (frames counted from job start):
//   (inputs 1..3 reach the pix by physical cords when their matrices are
//    banged at job start; the pix re-renders every frame on its own)
//   frame W+1       open bench_gate (before this frame's texture arrives)
//   frame W+2       close gate, write out.jxf, finish
// where W = job.warmup. A watchdog Task marks the job "stalled" after
// job.timeout_ms.

autowatch = 1;
inlets = 3;
outlets = 1;

var N_SLOTS = 8;
var MAX_INPUTS = 3;

var job = null;        // parsed job.json of the active job, or null
var jobDir = null;     // its directory (string, as received)
var errors = [];       // Max errors captured while the job is active
var frames = 0;        // draw bangs seen while the job is active
var output = null;     // output file name, if one was written
var extra = {};        // mode-specific result fields (e.g. fps)
var t0 = 0;
var delayTask = null;
var watchdog = null;

function anything() {
    var args = arrayfromargs(arguments);
    if (inlet === 0) {
        guarded(function () { handleOsc(messagename, args); });
    }
}

// Max errors, via [error 1] -> [deferlow] -> [prepend bench_error].
// Must never itself post an error or throw: that re-enters through [error].
// (2026-09-22: a direct [error] -> js wire recursed into a Max stack
// overflow, which disables all outlets until cleared.)
var MAX_ERRORS = 50;
var inErrorHandler = false;
function bench_error() {
    if (inErrorHandler || !job) return;
    inErrorHandler = true;
    try {
        if (errors.length < MAX_ERRORS) {
            var words = arrayfromargs(arguments);
            if (words.length && words[0] === "error") words.shift();
            errors.push(words.join(" "));
        }
    } catch (e) {
        // swallow: reporting from here would loop
    }
    inErrorHandler = false;
}

function bang() {
    if (inlet !== 2 || !job) return;
    frames++;
    if (frames === PARAM_FRAME && job.mode !== "stub" && job.mode !== "stub_delay") {
        guarded(applyParams);
    }
    if (job.mode === "correctness") guarded(correctnessFrame);
    else if (job.mode === "temporal") guarded(temporalFrame);
    else if (job.mode === "performance" && perf) guarded(performanceFrame);
}

// Run f; turn any JS exception into a job error (finishing the job) instead
// of letting it post to the Max window.
function guarded(f) {
    try {
        f();
    } catch (e) {
        if (job) {
            finish("error", "bench.js exception: " + e);
        } else {
            post("bench.js exception: " + e + "\n");
        }
    }
}

function handleOsc(address, args) {
    if (address === "/ping") {
        outlet(0, "/pong");
    } else if (address === "/run") {
        var dir = String(args.join(" "));
        if (job) {
            outlet(0, "/busy", dir);
            return;
        }
        startJob(dir);
    } else if (address === "/close") {
        // lets benchclient.reopen() load a regenerated bench.maxpat without
        // manual steps; deferred so we're not inside our own handler
        if (job) {
            outlet(0, "/busy", "close");
            return;
        }
        outlet(0, "/closing");
        var pat = this.patcher;
        var t = new Task(function () { pat.wclose(); }, this);
        t.schedule(50);
    } else {
        post("bench: unknown message " + address + "\n");
    }
}

function startJob(dir) {
    jobDir = dir;
    errors = [];
    frames = 0;
    output = null;
    extra = {};
    t0 = Date.now();
    var text = readText(dir + "/job.json");
    var parsed = null;
    try {
        parsed = text === null ? null : JSON.parse(text);
    } catch (e) {
        parsed = null;
    }
    job = parsed || { id: "unknown", mode: "invalid" };
    if (!parsed) return finish("error", "cannot read or parse " + dir + "/job.json");

    if (job.mode === "stub") {
        finish("ok");
    } else if (job.mode === "stub_delay") {
        delayTask = new Task(function () { finish("ok"); }, this);
        delayTask.schedule(job.delay_ms || 1000);
    } else if (job.mode === "correctness") {
        startCorrectness();
    } else if (job.mode === "performance") {
        startPerformance();
    } else if (job.mode === "temporal") {
        startTemporal();
    } else {
        finish("error", "mode '" + job.mode + "' not implemented in this bench version");
    }
}

// ------------------------------------------------------------ correctness

function outName(k) { return k === 1 ? "bench_out" : "bench_out" + k; }
function gateName(k) { return k === 1 ? "bench_gate" : "bench_gate" + k; }

function startCorrectness() {
    for (var k = 1; k <= 4; k++) obj(outName(k)).message("dim", 1, 1);   // detect silent outlets
    setupSlots(1);
    loadInputs();
    startWatchdog();
}

// Slots 1..nActive get the job's gen/dim/type/params and bypass 0; the rest
// are bypassed. nActive = 0 bypasses everything.
function setupSlots(nActive) {
    for (var s = 1; s <= N_SLOTS; s++) {
        var p = obj("bench_p" + s);
        if (s > nActive) {
            p.message("bypass", 1);
            continue;
        }
        p.message("bypass", 0);
        p.message("adapt", 0);
        p.message("dim", job.dim[0], job.dim[1]);
        p.message("type", job.type || "float32");
        p.message("gen", job.gen);
        if (job.compile) p.message("compile");
    }
    activeSlots = nActive;
}

// Params go out on frame PARAM_FRAME, not with `gen`: a newly loaded gen
// compiles at its first render, and the draw bang fires BEFORE the render,
// so params sent earlier hit an uncompiled pix ("jit.gl.pix: invalid
// message <param>", seen 2026-09-22 at frames 0 and 1).
var PARAM_FRAME = 3;
function applyParams() {
    var params = job.params || {};
    for (var s = 1; s <= activeSlots; s++) {
        var p = obj("bench_p" + s);
        for (var k in params) {
            if (params.hasOwnProperty(k)) p.message.apply(p, [k].concat(params[k]));
        }
    }
}


function loadInputs() {
    var ins = job.inputs || [];
    for (var i = 0; i < ins.length && i < MAX_INPUTS; i++) {
        var m = obj("bench_in" + (i + 1));
        m.message("read", jobDir + "/" + ins[i]);
        m.message("bang");                       // upload to bench_tex(i+1)
    }
}

function correctnessFrame() {
    var w = Math.max(job.warmup || 5, PARAM_FRAME + 2);   // capture after params land
    if (frames === w + 1) {
        for (var k = 1; k <= 4; k++) obj(gateName(k)).message(1);
    } else if (frames === w + 2) {
        var got = [];
        for (var j = 1; j <= 4; j++) {
            obj(gateName(j)).message(0);
            var m = obj(outName(j)), d = m.getattr("dim");
            if (d && !(d[0] === 1 && d[1] === 1)) {
                m.message("write", jobDir + "/" + (j === 1 ? "out.jxf" : "out" + j + ".jxf"));
                got.push(j);
            }
        }
        output = got.indexOf(1) >= 0 ? "out.jxf" : null;
        extra.outputs = got;
        finish(errors.length ? "error" : "ok");
    }
}

// ------------------------------------------------------------ temporal (E4)
// Step s (1-based) renders on frame S0 + s - 1, S0 = first frame after params.
// At the start of frame S0 (draw bang precedes the textures) js re-uploads the
// initial state into in2/in3 and enables feedback, so step 1 reads the
// initial state and step s reads step s-1's output. Captures: gates open at
// the start of step s's frame, written at the start of the next frame (before
// its textures), so consecutive steps can be captured.

var temporal = null;

function startTemporal() {
    for (var k = 1; k <= 4; k++) obj(outName(k)).message("dim", 1, 1);
    obj("bench_fbsel").message(0);
    obj("bench_fbgate").message(0);
    obj("bench_fb").message("type", job.type || "float32");
    setupSlots(1);
    loadInputs();
    var fb = job.feedback || { from_out: 1, to_in: 2 };
    var steps = (job.steps || [1]).slice().sort(function (a, b) { return a - b; });
    temporal = { S0: Math.max(job.warmup || 5, PARAM_FRAME + 2), fb: fb, steps: steps,
                 last: steps[steps.length - 1], open: null, captures: {} };
    startWatchdog();
}

function temporalFrame() {
    var t = temporal, step = frames - t.S0 + 1;
    if (step < 1) return;
    if (t.open !== null) {                            // write the step captured last frame
        var got = [];
        for (var k = 1; k <= 4; k++) {
            obj(gateName(k)).message(0);
            var m = obj(outName(k)), d = m.getattr("dim");
            if (d && !(d[0] === 1 && d[1] === 1)) {
                m.message("write", jobDir + "/out" + k + "_s" + t.open + ".jxf");
                got.push(k);
            }
        }
        t.captures[t.open] = got;
        if (t.open === t.last) {
            obj("bench_fbsel").message(0);
            obj("bench_fbgate").message(0);
            extra.captures = t.captures;
            temporal = null;
            finish(errors.length ? "error" : "ok");
            return;
        }
        t.open = null;
    }
    if (step === 1) {
        var ti = t.fb.to_in;                          // re-upload initial state, enable feedback
        obj("bench_in" + ti).message("bang");
        obj("bench_fbsel").message(t.fb.from_out);
        obj("bench_fbgate").message(ti - 1);
    }
    if (t.steps.indexOf(step) >= 0) {
        for (var j = 1; j <= 4; j++) obj(gateName(j)).message(1);
        t.open = step;
    }
}

// ------------------------------------------------------------ performance
// Phases: warmup_k -> measure_k -> (bypass all) warmup_0 -> measure_0.
// Rate control: world displaylink 0 + sync 0 + fps target_fps for the job,
// restored afterwards. (2026-09-22: default displaylink 1 locks the world to
// the display swap, ~118 fps here, regardless of `fps`.)
// fps = frames counted in a measure_ms window / elapsed -- whole-frame
// wall-clock throughput. CPU and GPU overlap: frame time ~= max(CPU
// overhead, K * pass cost), so per-pass cost is only resolvable when the run
// is GPU-bound (benchclient.measure works this out).

var perf = null;
var activeSlots = 0;

function startPerformance() {
    var K = Math.max(0, Math.min(job.chain === undefined ? 1 : job.chain, N_SLOTS));
    var w = obj("bench_world");
    perf = {
        K: K,
        saved: {
            displaylink: w.getattr("displaylink"),
            sync: w.getattr("sync"),
            fps: w.getattr("fps")
        },
        phase: "warmup_k",
        phaseStart: Date.now(),
        phaseFrames: 0
    };
    w.message("displaylink", 0);
    w.message("sync", 0);
    w.message("fps", job.target_fps || 1000);
    setupSlots(K);
    loadInputs();
    startWatchdog();
}

function perfPhase(name) {
    perf.phase = name;
    perf.phaseStart = Date.now();
    perf.phaseFrames = 0;
}

function performanceFrame() {
    var now = Date.now();
    var W = Math.max(job.warmup || 30, PARAM_FRAME + 2);
    var M = job.measure_ms || 1000;
    var elapsed = now - perf.phaseStart;
    perf.phaseFrames++;
    if (perf.phase === "warmup_k" && perf.phaseFrames >= W) {
        perfPhase("measure_k");
    } else if (perf.phase === "measure_k" && elapsed >= M) {
        extra.fps = perf.phaseFrames * 1000 / elapsed;
        extra.frames_measured_k = perf.phaseFrames;
        setupSlots(0);
        perfPhase("warmup_0");
    } else if (perf.phase === "warmup_0" && perf.phaseFrames >= W) {
        perfPhase("measure_0");
    } else if (perf.phase === "measure_0" && elapsed >= M) {
        extra.fps_baseline_k0 = perf.phaseFrames * 1000 / elapsed;
        extra.frames_measured_k0 = perf.phaseFrames;
        extra.chain = perf.K;
        extra.measure_ms = M;
        extra.rate_control = "displaylink 0, sync 0, fps " + (job.target_fps || 1000);
        finish(errors.length ? "error" : "ok");
    }
}

function restorePerf() {
    if (!perf) return;
    var w = obj("bench_world");
    var sv = perf.saved;
    w.message.apply(w, ["displaylink"].concat(sv.displaylink));
    w.message.apply(w, ["sync"].concat(sv.sync));
    w.message.apply(w, ["fps"].concat(sv.fps));
    perf = null;
}


function startWatchdog() {
    var id = job.id;
    watchdog = new Task(function () {
        if (job && job.id === id) {
            finish("stalled", "no capture within " + (job.timeout_ms || 10000) +
                   " ms (" + frames + " frames seen)");
        }
    }, this);
    watchdog.schedule(job.timeout_ms || 10000);
}

// ------------------------------------------------------------ finish

function finish(status, extraError) {
    if (extraError) errors.push("bench: " + extraError);
    if (watchdog) { watchdog.cancel(); watchdog = null; }
    restorePerf();
    for (var gk = 1; gk <= 4; gk++) { var gate = obj(gateName(gk)); if (gate) gate.message(0); }
    var result = {
        id: job.id,
        status: status,
        errors: errors,
        frames_rendered: frames,
        output: output,
        fps: null,
        fps_baseline_k0: null,
        elapsed_ms: Date.now() - t0
    };
    for (var key in extra) {
        if (extra.hasOwnProperty(key)) result[key] = extra[key];
    }
    var dir = jobDir;
    if (!writeText(dir + "/result.json", JSON.stringify(result, null, 2))) {
        post("bench: could not write result.json in " + dir + "\n");
    }
    job = null;
    jobDir = null;
    delayTask = null;
    outlet(0, "/done", dir);
}

// ------------------------------------------------------------ helpers

function obj(name) {
    var o = this.patcher.getnamed(name);
    if (!o) post("bench: no object named " + name + "\n");
    return o;
}

function readText(path) {
    var f = new File(path, "read");
    if (!f.isopen) return null;
    var out = "";
    while (f.position < f.eof) {
        out += f.readstring(Math.min(1024, f.eof - f.position));
    }
    f.close();
    return out;
}

function writeText(path, s) {
    var f = new File(path, "write", "TEXT");
    if (!f.isopen) return false;
    f.eof = 0;
    f.writestring(s);
    f.close();
    return true;
}
